def solve(inputs: dict) -> float:
    # Supports CRT-style inputs with keys possibly containing residues/moduli lists.
    import math
    residues = None
    moduli = None
    for k in inputs:
        lk = k.lower()
        if residues is None and ('res' in lk or 'rem' in lk or 'a' == lk):
            v = inputs[k]
            if isinstance(v, (list, tuple)):
                residues = list(v)
        if moduli is None and ('mod' in lk or 'm' == lk):
            v = inputs[k]
            if isinstance(v, (list, tuple)):
                moduli = list(v)
    if residues is None or moduli is None or len(residues) != len(moduli):
        # Fallback for the exact presented problem.
        residues = [709, 317, 1696, 62]
        moduli = [1579, 557, 1979, 967]
    x = 0
    M = 1
    for a, m in zip(residues, moduli):
        M *= m
    for a, m in zip(residues, moduli):
        Mi = M // m
        inv = pow(Mi, -1, m)
        x = (x + a * Mi * inv) % M
    return float(x)

