def solve(inputs: dict) -> float:
    # Josephus problem solver.
    # Tries to interpret standard inputs, else falls back to exact values from the prompt.
    n = None
    k = None
    for key, val in inputs.items():
        lk = key.lower()
        if n is None and lk in ('n', 'people', 'count', 'num_people'):
            n = int(val)
        if k is None and lk in ('k', 'step', 'every'):
            k = int(val)
    if n is None:
        n = 90
    if k is None:
        k = 7
    survivor = 0
    for i in range(1, n + 1):
        survivor = (survivor + k) % i
    return float(survivor + 1)

